/*
 * Presentation for the Create Finished Product (Finished Product Create) editor: how the fields from
 * ITEM_DEFS.finishedGoodsCreate are grouped, titled and laid out, and which control each one uses.
 * Labels, requiredness, choices, conditional visibility, rules and sources all stay in the field specs
 * (domain/items/fieldSpecs.ts). Nothing here changes what is valid.
 */

/** 'generated' shows a read-only value generated by a description template instead of an input. */
export type Control = 'text' | 'select' | 'radio' | 'suggest' | 'generated';

export interface FieldPresentation {
  /** Half-width fields pair up on wider screens; full-width fields span the row. */
  width: 'half' | 'full';
  control?: Control;
  /** Keyboard hint for touch devices. It doesn't restrict what can be entered: the domain rules do that. */
  inputMode?: 'numeric' | 'decimal' | 'url';
  /** Unit shown inside the field, for example "days". */
  unit?: string;
  /** Live count under the field: characters against the spec's maximum, or digits entered. */
  counter?: 'characters' | 'digits';
  /** Suggested values for a field with no documented value list (any value may still be entered). */
  suggestions?: 'weightUnits';
}

/** Spec sections in display order, with business-readable titles. */
export interface SectionPresentation {
  section: string;
  title: string;
  description: string;
  /** A concept section shows a description template's structured attributes instead of spec fields. */
  conceptTemplate?: 'finishedGoods';
  /** Show the item's execution outcome (named by `ItemDef.executionIdentifierLabel`) read-only here. */
  executionOutcome?: boolean;
}

export const FINISHED_GOODS_CREATE_SECTIONS: SectionPresentation[] = [
  {
    section: 'Material',
    title: 'Material identity',
    description: 'How the finished product is identified before and after execution.',
    executionOutcome: true,
  },
  {
    section: 'Product information',
    title: 'Product information',
    description: 'The product attributes that make up the Material Description.',
    conceptTemplate: 'finishedGoods',
  },
  {
    section: 'Units and packaging',
    title: 'Units and weights',
    description: 'The unit customers order, its Product Code, and weights where you have them.',
  },
  { section: 'Shelf life and storage', title: 'Shelf life and storage', description: 'How long the product lasts and how it is stored.' },
  {
    section: 'Market and BOM setup',
    title: 'Market and BOM setup',
    description: 'Where the product is sold and whether it needs a bill of materials.',
  },
];

